 * DeleteConfirmDialog — React-style component pattern
 *
 * Manages: open/close, focus trap, keyboard handling, aria-hidden,
 * and restoring focus on close (WCAG 2.1 SC 2.1.2, 2.4.3).
 */

// ── Focusable elements selector ───────────────────────────────
const FOCUSABLE_SELECTORS = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(', ');

// ── DeleteConfirmDialog component ─────────────────────────────
function DeleteConfirmDialog({ backdropId, dialogId, triggerId, mainId }) {
  const backdrop  = document.getElementById(backdropId);
  const dialog    = document.getElementById(dialogId);
  const trigger   = document.getElementById(triggerId);
  const main      = document.getElementById(mainId);

  if (!backdrop || !dialog || !trigger) return;

  let previousFocus = null;

  // ── open ──────────────────────────────────────────────────
  function openDialog() {
    previousFocus = document.activeElement;

    backdrop.classList.add('is-open');
    dialog.removeAttribute('aria-hidden');
    backdrop.removeAttribute('aria-hidden');

    // Inert the rest of the page content while dialog is open
    if (main) main.setAttribute('inert', '');

    // Move focus into dialog after paint so transition is visible
    requestAnimationFrame(() => {
      const firstFocusable = dialog.querySelectorAll(FOCUSABLE_SELECTORS)[0];
      if (firstFocusable) firstFocusable.focus();
    });

    backdrop.addEventListener('keydown', handleKeyDown);
    backdrop.addEventListener('mousedown', handleBackdropClick);
  }

  // ── close ─────────────────────────────────────────────────
  function closeDialog() {
    backdrop.classList.remove('is-open');
    dialog.setAttribute('aria-hidden', 'true');

    if (main) main.removeAttribute('inert');

    backdrop.removeEventListener('keydown', handleKeyDown);
    backdrop.removeEventListener('mousedown', handleBackdropClick);

    // Restore focus to the element that opened the dialog
    if (previousFocus) previousFocus.focus();
    previousFocus = null;
  }

