/**
 * DeleteConfirmDialog — React-style component pattern
 *
 * Manages: open/close, focus trap, keyboard handling, aria-hidden,
 * and restoring focus on close (WCAG 2.1 SC 2.1.2, 2.4.3).
 */

// ── Focusable elements selector ───────────────────────────────
const FOCUSABLE_SELECTORS = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(', ');

// ── DeleteConfirmDialog component ─────────────────────────────
function DeleteConfirmDialog({ backdropId, dialogId, triggerId, mainId }) {
  const backdrop  = document.getElementById(backdropId);
  const dialog    = document.getElementById(dialogId);
  const trigger   = document.getElementById(triggerId);
  const main      = document.getElementById(mainId);

  if (!backdrop || !dialog || !trigger) return;

  let previousFocus = null;

